selector_to_html = {"a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-tsingmicro.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Tsingmicro\uff08\u6e05\u5fae\u667a\u80fd\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/tsingmicro/\">tsingmicro</a>3.6<a class=\"headerlink\" href=\"#tsingmicro-tsingmicro3-6\" title=\"Link to this heading\">#</a></h1><h2>1. \u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><h3>1.1 \u4f7f\u7528\u955c\u50cf\uff08TX81\uff09<a class=\"headerlink\" href=\"#tx81\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-sunrise.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Sunrise\uff08\u66e6\u671b\u82af\u79d1\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/sunrise/\">sunrise</a>3.6<a class=\"headerlink\" href=\"#sunrise-sunrise3-6\" title=\"Link to this heading\">#</a></h1><h2>1. \u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><h3>1.1 \u4f7f\u7528\u955c\u50cf\uff08S2\uff09<a class=\"headerlink\" href=\"#s2\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-spacemit.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab SpacemiT\uff08\u8fdb\u8fed\u65f6\u7a7a\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/spacemit/\">spacemit</a>3.6<a class=\"headerlink\" href=\"#spacemit-spacemit3-6\" title=\"Link to this heading\">#</a></h1><h2>1. \u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><h3>1.1 \u4f7f\u7528\u955c\u50cf\uff08x64 emulation environment\uff09<a class=\"headerlink\" href=\"#x64-emulation-environment\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-iluvatar.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab ILUVATAR\uff08\u5929\u6570\u667a\u82af\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/iluvatar/\">iluvatar</a>3.6<a class=\"headerlink\" href=\"#iluvatar-iluvatar3-6\" title=\"Link to this heading\">#</a></h1><h2>1. \u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><h3>1.1 \u4f7f\u7528\u955c\u50cf\uff08BI-V150\uff09<a class=\"headerlink\" href=\"#bi-v150\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../user_guide/use-tle-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 TLE-CPU<a class=\"headerlink\" href=\"#tle-cpu\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528 TLE-CPU\u3002TLE-CPU \u5728 trition_3.3.x \u5206\u652f\u4e0a\u53ef\u7528\u3002</p><p>TLE-CPU \u63d0\u4f9b\u7edf\u4e00\u7684\u7f16\u7a0b\u8303\u5f0f\uff0c\u8986\u76d6\u591a\u6837\u5316\u7684\u8fb9\u7f18\u7aef CPU \u7b97\u529b\u3002\u5c06 TLE \u201c\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">@triton.jit</span></code> \u4e4b\u4e0a\u5206\u5c42\u786c\u4ef6\u6df1\u5ea6\u4f18\u5316\u201d\u7684\u7406\u5ff5\u6269\u5c55\u5230 CPU\u3002\u9488\u5bf9\u8fb9\u7f18 AI \u788e\u7247\u5316\u7684 CPU \u751f\u6001\uff08Arm64 / RISC-V / x86\uff0c\u591a\u79cd ISA \u5e76\u5b58\uff09\uff0c\u4f7f\u7528\u76f8\u540c\u7684 Triton \u7f16\u7a0b\u6a21\u578b\u548c\u96c6\u6210\u6846\u67b6\u6765\u652f\u6301\u4e0d\u540c\u7684 ISA\uff1a\u7f16\u7a0b\u6a21\u578b\u548c\u6b63\u786e\u6027\u8de8 ISA \u5171\u4eab\uff08\u666e\u901a Triton \u901a\u8fc7 LLVM \u843d\u5230\u4efb\u610f ISA\uff09\uff0c\u800c\u6bcf\u4e2a ISA \u7684\u9ad8\u6027\u80fd\u5b9e\u73b0\uff08intrinsic / C \u8fd0\u884c\u65f6\uff09\u5219\u5206\u522b\u8d21\u732e\u3002\u6a21\u578b\u4ee3\u7801\u901a\u8fc7\u7b97\u5b50\u5e93\uff08FlagGems\uff09\u7684 vendor \u5206\u53d1\u8def\u7531\u5230\u5bf9\u5e94\u7684 ISA \u5b9e\u73b0\uff0c\u65e0\u9700\u611f\u77e5\u5177\u4f53 ISA\u3002CPU \u4e0e GPU \u7684\u5dee\u5f02\u51b3\u5b9a\u4e86\u5b83\u9700\u8981\u4e00\u4e2a\u72ec\u7acb\u7684\u6269\u5c55\u9762\uff1a</p>", "a[href=\"#flagtree-0-7-0\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagTree 0.7.0 \u53d1\u5e03<a class=\"headerlink\" href=\"#flagtree-0-7-0\" title=\"Link to this heading\">#</a></h1>", "a[href=\"../getting_started/install-arm64-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5728 Arm64 CPU \u4e0a\u5b89\u88c5<a class=\"headerlink\" href=\"#arm64-cpu\" title=\"Link to this heading\">#</a></h1><p>\u5728 Arm64 CPU \u4e0a\u5b89\u88c5 FlagTree \u4e4b\u524d\uff0c\u8bf7\u9605\u8bfb\u4ee5\u4e0b\u6ce8\u610f\u4e8b\u9879\uff1a</p>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-ppu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab T-Head\uff08\u5e73\u5934\u54e5\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/ppu/\">ppu</a>3.6<a class=\"headerlink\" href=\"#t-head-ppu3-6\" title=\"Link to this heading\">#</a></h1><h2>1. \u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><h3>1.1 \u4f7f\u7528\u955c\u50cf\uff08810E|890P\uff09<a class=\"headerlink\" href=\"#e-890p\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-tileir.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab NVIDIA TileIR <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/tileir/\">tileir</a>3.6<a class=\"headerlink\" href=\"#nvidia-tileir-tileir3-6\" title=\"Link to this heading\">#</a></h1><h2>1. \u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><h3>1.1 \u4f7f\u7528\u955c\u50cf\uff08Hopper/Blackwell\uff09<a class=\"headerlink\" href=\"#hopper-blackwell\" title=\"Link to this heading\">#</a></h3><p>\u8be5\u955c\u50cf\u4e5f\u53ef\u7528\u4e8e <code class=\"docutils literal notranslate\"><span class=\"pre\">nvidia</span></code> \u540e\u7aef\u3002</p>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-amd.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab AMD <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/amd/\">amd</a><a class=\"headerlink\" href=\"#amd-amd\" title=\"Link to this heading\">#</a></h1><h2>1. \u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><h3>1.1 \u4f7f\u7528\u955c\u50cf\uff08Triton 3.6\uff09<a class=\"headerlink\" href=\"#triton-3-6\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-rpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab Huixi Intelligence\uff08\u8f89\u7fb2\u667a\u80fd\uff09<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/rpu/\">rpu</a>3.6<a class=\"headerlink\" href=\"#huixi-intelligence-rpu3-6\" title=\"Link to this heading\">#</a></h1><p><strong>Rhino RPU</strong> \u662f\u8f89\u7fb2\u667a\u80fd\u5149\u81f3 R1 SoC \u5185\u7684 AI \u52a0\u901f\u5668\n\uff08<a class=\"reference external\" href=\"https://www.rhino.auto/\">rhino.auto</a>\uff09\u3002\u4e0e CPU/GPU \u540e\u7aef\u4e0d\u540c\uff0cRPU\n\u540e\u7aef<strong>\u6ca1\u6709\u9884\u88c5\u955c\u50cf\uff0c\u4e5f\u6ca1\u6709 CPU \u6a21\u62df\u5668</strong>\u2014\u2014\u5b83\u53ea\u80fd\u5728\n\u5b9e\u4f53 R1 SoC \u677f\u5361\u4e0a\u7f16\u8bd1\u4e0e\u8fd0\u884c\uff0c\u5176\u9a71\u52a8\u3001\u8fd0\u884c\u65f6\u548c\u5de5\u5177\u94fe\u9700\n\u5411\u5382\u5546\u83b7\u53d6\u3002\u8bf7\u76f4\u63a5\u5728\u677f\u5361\u4e0a\u6784\u5efa\u4e0e\u6d4b\u8bd5\u3002</p>", "a[href=\"../getting_started/multi-backend-prebuilt-docker-image-install/install-xpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab KLX <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/tree/main/third_party/xpu/\">xpu</a>3.6<a class=\"headerlink\" href=\"#klx-xpu3-6\" title=\"Link to this heading\">#</a></h1><h2>1. \u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><h3>1.1 \u4f7f\u7528\u955c\u50cf\uff08P800\uff09<a class=\"headerlink\" href=\"#p800\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
